Bagging promedia, boosting acumula. Agregar un árbol a un promedio de 100 casi no lo mueve, así que bagging se estabiliza. En boosting, cada árbol nuevo corrige al modelo, y cuando ya no queda señal, corrige el ruido: el error de prueba vuelve a subir. Por eso en boosting el número de árboles se elige con validación (early stopping).


R y Python no dan exactamente los mismos números: las particiones al azar y los detalles de cada implementación difieren. Lo que se debe repetir es el patrón: los conjuntos de árboles (bagging, random forest y boosting) le ganan al árbol solo.


ML = {
  const mulberry = seed =&gt; () =&gt; { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed &gt;&gt;&gt; 15, 1 | seed); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; };
  const gauss = r =&gt; { let u = 0, v = 0; while (!u) u = r(); while (!v) v = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const fVerdad = x =&gt; Math.sin(0.9 * x) * 1.6 + 0.25 * x;
  const simula = (n, seed) =&gt; { const r = mulberry(seed); return Array.from({length: n}, () =&gt; { const x = 10 * r(); return {x, y: fVerdad(x) + 0.7 * gauss(r)}; }); };
  const promedio = a =&gt; a.reduce((s, v) =&gt; s + v, 0) / a.length;
  const arbol = (D, depth, minLeaf = 1) =&gt; {
    const crece = (pts, d) =&gt; {
      const m = promedio(pts.map(p =&gt; p.y));
      if (d === 0 || pts.length &lt; 2 * minLeaf) return {v: m};
      const s = pts.slice().sort((a, b) =&gt; a.x - b.x), n = s.length;
      const tot = s.reduce((a, p) =&gt; a + p.y, 0), tot2 = s.reduce((a, p) =&gt; a + p.y * p.y, 0);
      let mejor = null, sl = 0, sl2 = 0;
      for (let k = 1; k &lt; n; k++) {
        sl += s[k - 1].y; sl2 += s[k - 1].y ** 2;
        if (k &lt; minLeaf || n - k &lt; minLeaf || s[k - 1].x === s[k].x) continue;
        const rss = (sl2 - sl * sl / k) + ((tot2 - sl2) - (tot - sl) ** 2 / (n - k));
        if (!mejor || rss &lt; mejor.rss) mejor = {rss, k};
      }
      if (!mejor) return {v: m};
      return {s: (s[mejor.k - 1].x + s[mejor.k].x) / 2, L: crece(s.slice(0, mejor.k), d - 1), R: crece(s.slice(mejor.k), d - 1)};
    };
    const t = crece(D, depth);
    return x =&gt; { let n = t; while (n.v === undefined) n = x &lt; n.s ? n.L : n.R; return n.v; };
  };
  const mse = (D, f) =&gt; D.reduce((s, d) =&gt; s + (d.y - f(d.x)) ** 2, 0) / D.length;
  const estilo = {style: {background: "#141A24", color: "#EEF2F7", fontFamily: "Public Sans", fontSize: "13px"}, marginLeft: 50, marginBottom: 42, grid: true};
  const ancho = w =&gt; Math.max(280, Math.floor((w - 60) / 2));
  return {mulberry, gauss, fVerdad, simula, arbol, mse, estilo, ancho};
}

bosques = {
  const train = ML.simula(50, 11), test = ML.simula(600, 999), r = ML.mulberry(123), B = 200, eta = 0.5;
  const bagF = [], boostF = [], curva = [];
  const sb = new Float64Array(test.length);
  for (let b = 1; b &lt;= B; b++) {
    const muestra = Array.from({length: train.length}, () =&gt; train[Math.floor(r() * train.length)]);
    const f = ML.arbol(muestra, 50, 1); bagF.push(f);
    test.forEach((d, i) =&gt; sb[i] += f(d.x));
    curva.push({b, m: "Bagging", error: test.reduce((s, d, i) =&gt; s + (d.y - sb[i] / b) ** 2, 0) / test.length});
  }
  const m0 = train.reduce((s, d) =&gt; s + d.y, 0) / train.length;
  let Ftr = train.map(() =&gt; m0), Fte = test.map(() =&gt; m0);
  for (let b = 1; b &lt;= B; b++) {
    const res = train.map((d, i) =&gt; ({x: d.x, y: d.y - Ftr[i]}));
    const h = ML.arbol(res, 3, 2); boostF.push(h);
    Ftr = Ftr.map((f, i) =&gt; f + eta * h(train[i].x)); Fte = Fte.map((f, i) =&gt; f + eta * h(test[i].x));
    curva.push({b, m: "Boosting", error: test.reduce((s, d, i) =&gt; s + (d.y - Fte[i]) ** 2, 0) / test.length});
  }
  return {
    train, curva,
    bag: (x, n) =&gt; bagF.slice(0, n).reduce((s, f) =&gt; s + f(x), 0) / n,
    boost: (x, n) =&gt; boostF.slice(0, n).reduce((s, f) =&gt; s + eta * f(x), m0)
  };
}

pacientes = {
  const r = ML.mulberry(7), lim = v =&gt; Math.min(0.99, Math.max(0.01, v));
  return Array.from({length: 200}, (_, i) =&gt; {
    const enfermo = i &lt; 40;
    return {enfermo, prob: lim(enfermo ? 0.66 + 0.18 * ML.gauss(r) : 0.3 + 0.17 * ML.gauss(r)), j: (r() - 0.5) * 1.8};
  });
}

rocCurva = {
  const u = [1.01, ...pacientes.map(p =&gt; p.prob).sort((a, b) =&gt; b - a), 0];
  return u.map(t =&gt; ({fpr: pacientes.filter(p =&gt; !p.enfermo && p.prob &gt;= t).length / 160, tpr: pacientes.filter(p =&gt; p.enfermo && p.prob &gt;= t).length / 40}));
}

aucSim = {
  const E = pacientes.filter(p =&gt; p.enfermo), S = pacientes.filter(p =&gt; !p.enfermo);
  let a = 0; E.forEach(e =&gt; S.forEach(s =&gt; a += e.prob &gt; s.prob ? 1 : e.prob === s.prob ? 0.5 : 0));
  return a / (E.length * S.length);
}
